1	#!/usr/bin/env node
2	/**
3	 * stage0-post-audit.cjs — Consolidated Stage0 Audit Hook
4	 *
5	 * Merges 8 individual stage0 hooks into one file. Reads stdin ONCE.
6	 * Auto-routes by payload shape:
7	 *   - Has tool_name → PreToolUse → cashflow audit (audit 8)
8	 *   - No tool_name  → Stop hook  → audits 1-7
9	 *
10	 * Stop exit codes: 0 = pass, 2 = BLOCK (first failure wins)
11	 * PreToolUse output: JSON { decision: 'approve'|'block'|'allow', reason? }
12	 */
13	
14	'use strict';
15	
16	const fs = require('fs');
17	const path = require('path');
18	const os = require('os');
19	const { spawnSync } = require('child_process');
20	
21	let isHookEnabled;
22	try { ({ isHookEnabled } = require('./lib/ck-config-utils.cjs')); }
23	catch { isHookEnabled = () => true; }
24	
25	if (!isHookEnabled('stage0-post-audit')) process.exit(0);
26	
27	// Read stdin ONCE — shared by all audits
28	let payload = {};
29	try {
30	  const raw = fs.readFileSync(0, 'utf-8').trim();
31	  if (raw) payload = JSON.parse(raw);
32	} catch { process.exit(0); }
33	
34	if (typeof payload.tool_name === 'string') runCashflowAudit(payload);
35	else runStopAudits(payload);
36	
37	// ── Shared helpers ─────────────────────────────────────────────────────────────
38	
39	function getLastAssistantText(p) {
40	  if (p.transcript_path && fs.existsSync(p.transcript_path)) {
41	    try {
42	      const lines = fs.readFileSync(p.transcript_path, 'utf8').trim().split('\n');
43	      for (let i = lines.length - 1; i >= 0; i--) {
44	        const e = JSON.parse(lines[i]);
45	        if (e.type === 'assistant' || e.role === 'assistant') {
46	          const c = e.content || e.message?.content;
47	          if (typeof c === 'string') return c;
48	          if (Array.isArray(c)) return c.filter(b => b.type === 'text' || !b.type).map(b => b.text || b.content || '').join('\n');
49	        }
50	      }
51	    } catch {}
52	  }
53	  return p.assistant_message || p.message || p.text || '';
54	}
55	
56	function looksLikeVerdict(text) {
57	  if (!text || text.length < 500) return false;
58	  return [/\/stage0 verdict/i, /mountain test v2/i, /brain information flow audit/i, /verdict class/i, /VERDICT:/i]
59	    .filter(r => r.test(text)).length >= 2;
60	}
61	
62	function getRecentIntentClass() {
63	  try {
64	    const tmpDir = os.tmpdir();
65	    const files = fs.readdirSync(tmpDir)
66	      .filter(f => f.startsWith('stage0-intent-class-') && f.endsWith('.json'))
67	      .map(f => ({ name: f, mtime: fs.statSync(path.join(tmpDir, f)).mtimeMs }))
68	      .sort((a, b) => b.mtime - a.mtime);
69	    if (!files.length) return null;
70	    return JSON.parse(fs.readFileSync(path.join(tmpDir, files[0].name), 'utf8')).intent_class || null;
71	  } catch { return null; }
72	}
73	
74	function isStage0ViaTmpFiles() {
75	  try {
76	    const files = fs.readdirSync(os.tmpdir());
77	    return files.some(f => f.startsWith('stage0-intent-class-') || f.startsWith('stage0-runtime-assertions-'));
78	  } catch { return false; }
79	}
80	
81	// ══════════════════════════════════════════════════════════════════════════════
82	// STOP AUDITS (1-7)
83	// ══════════════════════════════════════════════════════════════════════════════
84	
85	function runStopAudits(payload) {
86	  const msg   = payload.assistant_message || payload.last_message || payload.content || '';
87	  const user  = payload.user_prompt || payload.last_user_message || '';
88	  const trans = payload.transcript || '';
89	
90	  const MARKERS = ['/stage0', '/ck:stage0'];
91	  const isStage0 = MARKERS.some(m =>
92	    (user || '').toLowerCase().includes(m) || (trans || '').toLowerCase().includes(m)
93	  );
94	  // Gate check also matches 'stage 0' in assistant message
95	  const isStage0Gate = isStage0 || ['stage 0'].some(m => msg.toLowerCase().includes(m));
96	
97	  const hayLow  = (msg + '\n' + trans).toLowerCase();
98	  const hayOrig = msg + '\n' + trans;
99	  const hasVerdict = /##\s*verdict:/i.test(msg);
100	
101	  const blocks = [];
102	  const warnings = [];
103	
104	  // 1. Parallel tracks + disclaimer
105	  auditParallelTracks(payload, msg, isStage0 || isStage0ViaTmpFiles(), blocks);
106	  // 2. Agent dispatch count
107	  if (isStage0) auditDispatchEnforcer(msg, hayLow, hasVerdict, warnings, blocks);
108	  // 3. Python quality gate
109	  if (isStage0Gate) auditGateEnforcement(msg, blocks);
110	  // 4. Persist scripts + verdict structure
111	  if (isStage0) auditToolCalls(msg, hayLow, hayOrig, warnings, blocks);
112	  // 5. Content extraction (warn-only)
113	  if (isStage0 && hasVerdict) auditContentExtraction(msg, user, hayLow, warnings);
114	  // 6. Claim verification (warn-only)
115	  if (isStage0 && hasVerdict) auditClaimVerification(msg, user, hayLow, warnings);
116	  // 7. Wave 2 receipt
117	  auditWave2(payload, msg, blocks);
118	
119	  if (warnings.length) process.stderr.write(warnings.join('\n') + '\n');
120	  if (blocks.length) { process.stderr.write(blocks[0] + '\n'); process.exit(2); }
121	  process.exit(0);
122	}
123	
124	// ── Audit 1: Parallel Tracks ───────────────────────────────────────────────────
125	
126	function auditParallelTracks(payload, msg, active, blocks) {
127	  if (!active) return;
128	  const text = msg || getLastAssistantText(payload);
129	  if (!looksLikeVerdict(text)) return;
130	
131	  const missing = [];
132	  if (!/##\s+short\s+track/i.test(text))   missing.push('## Short track (cash path <90d)');
133	  if (!/##\s+medium\s+track/i.test(text))  missing.push('## Medium track (asset path 3-12mo)');
134	  if (!/##\s+long\s+track/i.test(text))    missing.push('## Long track (moat path >12mo)');
135	
136	  const intent = getRecentIntentClass();
137	  if (intent === 'grey_zone_adjacent' && !/##\s+legal\s+boundary\s+disclaimer/i.test(text))
138	    missing.push('## Legal Boundary Disclaimer (required for grey_zone_adjacent)');
139	
140	  if (missing.length) {
141	    blocks.push([
142	      '[stage0-parallel-tracks-check] BLOCK: verdict missing required sections',
143	      `Missing: ${missing.join(', ')}`,
144	      "Real founders run concurrent tracks. Empty tracks must say 'N/A — reason'.",
145	      'Regenerate with all required sections.',
146	    ].join('\n'));
147	  }
148	}
149	
150	// ── Audit 2: Dispatch Enforcer ─────────────────────────────────────────────────
151	
152	const REQUIRED_AGENTS = [
153	  'schema-accumulator','persona-loader','contrarian-research-agent','market-reality-checker',
154	  'failure-archaeologist','competitive-intelligence-engine','deep-comment-miner','topic-spider',
155	  'ground-truth-fetcher','full-coverage-ingest','knowledge-graph-curator','persona-insider-loader',
156	  'financial-triangulator','hypothesis-generator',
157	];
158	
159	function auditDispatchEnforcer(msg, hayLow, hasVerdict, warnings, blocks) {
160	  if (!msg || msg.length < 50 || !hasVerdict) return;
161	
162	  if (!hayLow.includes('routing_context') && !hayLow.includes('capital tier:'))
163	    warnings.push('⚠ STAGE0: ROUTING_CONTEXT not found — local orchestrator may not have run');
164	
165	  const tierM = hayLow.match(/capital tier:\s*(tier_\d)/i);
166	  if (tierM && ['tier_0','tier_1'].includes(tierM[1]) && hayLow.includes('$10k/mo'))
167	    warnings.push(`⚠ STAGE0: TIER mismatch: ${tierM[1].toUpperCase()} founder targeting $10K/mo`);
168	
169	  const detected = REQUIRED_AGENTS.filter(n => hayLow.includes(n));
170	  const missing  = REQUIRED_AGENTS.filter(n => !hayLow.includes(n));
171	
172	  if (detected.length >= 10) return;
173	
174	  blocks.push([
175	    `STAGE0 DISPATCH ENFORCER — BLOCKED (${detected.length}/14 agents, min 10)`,
176	    `Missing: ${missing.join(', ')}`,
177	    'Spawn missing agents before producing verdict.',
178	  ].join('\n'));
179	}
180	
181	// ── Audit 3: Python Quality Gate ──────────────────────────────────────────────
182	
183	function auditGateEnforcement(msg, blocks) {
184	  if (!msg || msg.length < 200) return;
185	
186	  const tmpFile = path.join(os.tmpdir(), `stage0-gate-${Date.now()}.md`);
187	  try { fs.writeFileSync(tmpFile, msg, 'utf-8'); } catch { return; }
188	
189	  const root    = path.resolve(__dirname, '..', '..');
190	  const python  = path.join(root, '.claude', 'skills', '.venv', 'Scripts', 'python.exe');
191	  const script  = path.join(root, '.claude', 'skills', 'business', 'transaction-layer', 'scripts', 'stage0_quality_gate.py');
192	
193	  if (!fs.existsSync(python) || !fs.existsSync(script)) { try { fs.unlinkSync(tmpFile); } catch {} return; }
194	
195	  const res = spawnSync(python, [script, '--input', tmpFile, '--json'], { encoding: 'utf-8', timeout: 30000 });
196	  try { fs.unlinkSync(tmpFile); } catch {}
197	
198	  if (res.error) return;
199	  let verdict;
200	  try { verdict = JSON.parse(res.stdout || '{}'); } catch { return; }
201	  if (!verdict || verdict.overall_pass) return;
202	
203	  const failed = (verdict.gates || []).filter(g => !g.pass).map(g => `  [${g.id}] ${g.name}: ${g.detail}`).join('\n');
204	  blocks.push([
205	    `STAGE0 QUALITY GATE FAILED (${verdict.passed}/${verdict.total} passed)`,
206	    failed,
207	    'Regenerate addressing each failed gate.',
208	  ].join('\n'));
209	}
210	
211	// ── Audit 4: Tool Call Audit ───────────────────────────────────────────────────
212	
213	function auditToolCalls(msg, hayLow, hayOrig, warnings, blocks) {
214	  if (!msg || msg.length < 50) return;
215	
216	  const scripts = [
217	    { name: 'persist-verdict.py',   step: 'Step 9',   regex: /python(?:\.exe)?\s+[^\n]{0,200}persist-verdict\.py/i },
218	    { name: 'persist-knowledge.py', step: 'Step 9.5', regex: /python(?:\.exe)?\s+[^\n]{0,200}persist-knowledge\.py/i },
219	    { name: 'verify-persistence.py',step: 'Step 9.6', regex: /python(?:\.exe)?\s+[^\n]{0,200}verify-persistence\.py/i },
220	  ];
221	  const missingScripts = scripts.filter(s => !s.regex.test(hayOrig));
222	  const hasBrainAudit  = hayLow.includes('brain information flow audit') || hayLow.includes('## brain information flow');
223	  const hasVerdictMark = /##\s*verdict:\s*(mountain|provisional_mountain|side_hustle|insufficient_signal|kill)/i.test(hayOrig);
224	  const hasKBFired     = hayLow.includes('knowledge fired during this analysis') || hayLow.includes('## knowledge fired');
225	
226	  if (!/(?:interpret.*topic|branches?\s*detect|echo.*interpret|which.*branch)/i.test(hayOrig))
227	    warnings.push('⚠ STAGE0 SOFT: No topic disambiguation evidence. Consider Step 2.5 echo.');
228	
229	  const isKill = /VERDICT:\s*KILL/i.test(hayOrig);
230	  const usesMM03 = /MM-03|revenue.{0,30}floor|triangulat.{0,20}auto.?kill/i.test(hayOrig);
231	  if (isKill && usesMM03 && !/triangulated_range|burn_math|financial.triangulator.*return/i.test(hayOrig)
232	      && !/MM-03.*(?:INCONCLUSIVE|skipped|did not run)/i.test(hayOrig))
233	    warnings.push('⚠ STAGE0 SOFT: KILL via MM-03 without financial-triangulator data. Use INCONCLUSIVE or cite other grounds.');
234	
235	  const failures = [];
236	  if (missingScripts.length) failures.push(`Missing scripts: ${missingScripts.map(s => `${s.name} (${s.step})`).join(', ')}`);
237	  if (!hasBrainAudit)  failures.push('Missing ## Brain Information Flow Audit section');
238	  if (!hasVerdictMark) failures.push('Missing deterministic VERDICT marker');
239	  if (!hasKBFired)     failures.push('Missing ## Knowledge fired during this analysis section');
240	
241	  if (failures.length) {
242	    blocks.push([
243	      'STAGE0 TOOL CALL AUDIT — BLOCKED',
244	      failures.map((f, i) => `  ${i+1}. ${f}`).join('\n'),
245	      'Regenerate with all 6 required elements (scripts + sections + verdict marker).',
246	    ].join('\n'));
247	  }
248	}
249	
250	// ── Audit 5: Content Extraction (warn-only) ────────────────────────────────────
251	
252	function auditContentExtraction(msg, user, hayLow, warnings) {
253	  if (!msg || msg.length < 200) return;
254	  const urls = (user || '').match(/https?:\/\/[^\s)>"'\]]+/gi) || [];
255	  if (!urls.length) return;
256	
257	  const hasEvidence = [/yt-dlp/i,/tikwm/i,/dump-json/i,/write-info-json/i,/flat-playlist/i,
258	    /comment.*list.*api/i,/ai-multimodal/i,/deep.comment.miner/i,/transcript/i,/audio.transcrib/i,
259	    /whisper/i,/\.json\s*endpoint/i].some(r => r.test(hayLow));
260	  if (hasEvidence) return;
261	
262	  const platUrls = urls.filter(u => /tiktok\.com|youtube\.com|youtu\.be|reddit\.com|instagram\.com/i.test(u));
263	  warnings.push(`⚠ CONTENT EXTRACTION (${urls.length} URL(s), ${platUrls.length} platform): no extraction tool evidence. Use yt-dlp/tikwm/ai-multimodal per Step 2.7.`);
264	}
265	
266	// ── Audit 6: Claim Verification (warn-only) ────────────────────────────────────
267	
268	function auditClaimVerification(msg, user, hayLow, warnings) {
269	  if (!msg || msg.length < 200) return;
270	  const urls = (user || '').match(/https?:\/\/[^\s)>"'\]]+/gi) || [];
271	  if (!urls.length) return;
272	
273	  const w = [];
274	  const hasClaimSet = hayLow.includes('claim_set') || hayLow.includes('claim set') || hayLow.includes('claim expansion');
275	  if (!hasClaimSet) w.push(`${urls.length} URL(s) provided but no CLAIM_SET section — Step 2.8 may be skipped`);
276	
277	  if (/revenue|income|\$\d|earnings|profit/i.test(msg)
278	      && !/triangulat|3\+?\s*(?:independent|source)|cross.?verif/i.test(hayLow)
279	      && hasClaimSet)
280	    w.push('Revenue/income refs without triangulation evidence — P0 claims need 3+ source types');
281	
282	  if (w.length) warnings.push(`⚠ CLAIM VERIFICATION:\n${w.map((x,i)=>`  ${i+1}. ${x}`).join('\n')}`);
283	}
284	
285	// ── Audit 7: Wave 2 Enforcement ────────────────────────────────────────────────
286	
287	function auditWave2(payload, msg, blocks) {
288	  try {
289	    let enforceMode = 'enforce';
290	    try {
291	      const cfg = JSON.parse(fs.readFileSync(path.join(process.cwd(), '.claude', '.ck.json'), 'utf8'));
292	      enforceMode = cfg?.stage0?.wave2Enforcement || 'enforce';
293	    } catch {}
294	    if (enforceMode === 'off') return;
295	
296	    const tmpDir = os.tmpdir();
297	    const wave1 = fs.readdirSync(tmpDir)
298	      .filter(f => f.startsWith('stage0-wave1-receipt-') && f.endsWith('.json'))
299	      .map(f => ({ name: f, mtime: fs.statSync(path.join(tmpDir, f)).mtimeMs }))
300	      .sort((a, b) => b.mtime - a.mtime);
301	    if (!wave1.length) return;
302	
303	    const caseId = wave1[0].name.replace('stage0-wave1-receipt-', '').replace('.json', '');
304	    if (fs.existsSync(path.join(tmpDir, `stage0-wave2-receipt-${caseId}.json`))) return;
305	
306	    const text = msg || getLastAssistantText(payload);
307	    if (!looksLikeVerdict(text)) return;
308	
309	    const EXEMPT = new Set(['EXPLORATION_ONGOING','INSUFFICIENT_SIGNAL','KILL','HARD_KILL']);
310	    const vm = text.match(/VERDICT[:\s*]+([A-Z_]+)/);
311	    if (vm && EXEMPT.has(vm[1].trim())) return;
312	
313	    const BLOCKING_INTENTS = new Set(['operator_layer','power_law_hunt','grey_zone_adjacent']);
314	    let intentClass = null;
315	    try {
316	      const p = path.join(tmpDir, `stage0-intent-class-${caseId}.json`);
317	      if (fs.existsSync(p)) intentClass = JSON.parse(fs.readFileSync(p, 'utf8')).intent_class || null;
318	    } catch {}
319	
320	    if (intentClass && BLOCKING_INTENTS.has(intentClass)) {
321	      blocks.push(`[stage0-wave2-enforcement] HARD BLOCK: Wave 2 MANDATORY for ${intentClass}. Case ${caseId}. Spawn: deep-comment-miner, ground-truth-fetcher, full-coverage-ingest, financial-triangulator, persona-insider-loader, hypothesis-generator.`);
322	      return;
323	    }
324	
325	    const cm = text.match(/\*?\*?[Cc]onfidence[:\s*]+([0-9.]+)/);
326	    const conf = cm ? parseFloat(cm[1]) : 1.0;
327	    if (!isNaN(conf) && conf < 0.8) {
328	      const m = `[stage0-wave2-enforcement] BLOCK: Case ${caseId} | Conf ${conf} < 0.8 | Verdict ${vm?.[1]||'?'} | Intent ${intentClass||'?'}. Run Wave 2 (≥4 agents) OR downgrade to EXPLORATION_ONGOING.`;
329	      if (enforceMode === 'warn') process.stderr.write(m + '\n');
330	      else blocks.push(m);
331	    }
332	  } catch (e) {
333	    process.stderr.write(`[stage0-wave2-enforcement] error (fail-open): ${e.message}\n`);
334	  }
335	}
336	
337	// ══════════════════════════════════════════════════════════════════════════════
338	// PRETOOLUSE AUDIT (8) — CASHFLOW
339	// ══════════════════════════════════════════════════════════════════════════════
340	
341	function runCashflowAudit(payload) {
342	  if (payload.tool_name !== 'Write') { console.log(JSON.stringify({ decision: 'approve' })); return; }
343	
344	  const filePath = (payload.tool_input || payload.input || {}).file_path || '';
345	  const content  = (payload.tool_input || payload.input || {}).content  || '';
346	
347	  const AUDIT_PATHS = [/verdict.*\.md$/i,/verdicts\/.*\.md$/i,/startup.*output/i,/analysis.*\.md$/i,
348	    /circuit.*\.md$/i,/position.*\.md$/i,/stage0.*synthesis/i,/stage0-.*\.json$/i];
349	  const SKIP_PATHS  = [/node_modules/,/\.git/,/test/i,/spec/i,/plan\.md$/i,/phase-\d+/i];
350	
351	  if (!filePath || SKIP_PATHS.some(p => p.test(filePath)) || !AUDIT_PATHS.some(p => p.test(filePath))) {
352	    console.log(JSON.stringify({ decision: 'approve' })); return;
353	  }
354	
355	  const PATTERNS = [
356	    { pattern: /\$[\d,]+\s*(\/mo|MRR|ARR|month|monthly|revenue|income)/gi, engine: 'simulate' },
357	    { pattern: /\$[\d,]+k?\s*(per\s*month|a\s*month)/gi, engine: 'simulate' },
358	    { pattern: /(\d+)\s*(months?|weeks?|days?)\s*(runway|survive|last|left)/gi, engine: 'runway' },
359	    { pattern: /death\s*date|run\s*out\s*of\s*(cash|money)/gi, engine: 'runway' },
360	    { pattern: /survival\s*probability/gi, engine: 'runway' },
361	    { pattern: /(passive|leveraged|scalable|compound)\s*(income|revenue|business)/gi, engine: 'leverage' },
362	    { pattern: /leverage\s*score/gi, engine: 'leverage' },
363	    { pattern: /(price|charge|cost)\s*(at|of)?\s*\$[\d,]+/gi, engine: 'hormozi' },
364	    { pattern: /value\s*(equation|score)/gi, engine: 'hormozi' },
365	    { pattern: /(CCC|cash\s*conversion|payment\s*cycle)/gi, engine: 'velocity' },
366	    { pattern: /(DSO|DIO|DPO|days\s*receivable|days\s*payable)/gi, engine: 'velocity' },
367	    { pattern: /(nash\s*equilibrium|BATNA|power\s*balance)/gi, engine: 'game' },
368	    { pattern: /(walk[\s-]?away|negotiation\s*strategy)/gi, engine: 'game' },
369	    { pattern: /failure\s*mode|vulnerability|inversion/gi, engine: 'munger' },
370	    { pattern: /barbell\s*(allocation|strategy)/gi, engine: 'taleb' },
371	    { pattern: /breakeven\s*(in|by|month)\s*\d+/gi, engine: 'simulate' },
372	    { pattern: /monte\s*carlo/gi, engine: 'simulate' },
373	  ];
374	
375	  const violations = []; const seen = new Set();
376	  for (const { pattern, engine } of PATTERNS) {
377	    pattern.lastIndex = 0; let m;
378	    while ((m = pattern.exec(content)) !== null) {
379	      const lineNum = content.substring(0, m.index).split('\n').length;
380	      const key = `${lineNum}-${engine}`;
381	      if (seen.has(key)) continue; seen.add(key);
382	      const ctx = content.substring(Math.max(0, m.index - 250), Math.min(content.length, m.index + m[0].length + 100));
383	      if (!/\[COMPUTED:(\w+)\]/i.test(ctx) && !/\[UNCOMPUTED:(\w+)\|/i.test(ctx))
384	        violations.push({ claim: m[0].substring(0, 60) + (m[0].length > 60 ? '...' : ''), line: lineNum, engine });
385	    }
386	  }
387	
388	  if (!violations.length) { console.log(JSON.stringify({ decision: 'approve' })); return; }
389	
390	  const isDegraded = content.includes('MONEY_INTELLIGENCE_DEGRADED') || content.includes('[DEGRADED_NO_COMPUTATION]');
391	  if (isDegraded) {
392	    console.log(JSON.stringify({ decision: 'allow', additionalContext: `[stage0-cashflow-audit] DEGRADED: ${violations.length} uncomputed claims allowed` }));
393	    return;
394	  }
395	
396	  const list = violations.slice(0, 8).map(v => `  Line ${v.line}: "${v.claim}" → [COMPUTED:${v.engine}]`).join('\n')
397	    + (violations.length > 8 ? `\n  ... and ${violations.length - 8} more` : '');
398	  console.log(JSON.stringify({
399	    decision: 'block',
400	    reason: `CASHFLOW AUDIT FAILED: ${violations.length} uncomputed claim(s) in ${filePath}\n${list}\nRun money-calc-router.py and add [COMPUTED:engine] or [UNCOMPUTED:engine|reason:...] tags.`,
401	  }));
402	}
