// ── Audit 0: Agent Dispatch Evidence ──────────────────────────────────────────

function auditAgentDispatch(payload, msg, hayLow, active, warnings, blocks) {
  if (!active) return;
  const text = msg || getLastAssistantText(payload);
  if (!looksLikeVerdict(text)) return;

  // Patterns that indicate agent dispatch actually happened
  const DISPATCH_PATTERNS = [
    /Task\(/i, /subagent_type/i, /agents_fired/i,
    /Wave\s*1/i, /Wave\s*2/i,
    /agent.*returned/i, /agent.*spawned/i,
    /agent.*completed/i, /agent.*dispatched/i,
    /agent.*fired/i, /agent.*ran/i,
  ];

  // Also check for wave1-receipt in tmpdir
  let hasWave1Receipt = false;
  try {
    hasWave1Receipt = fs.readdirSync(os.tmpdir())
      .some(f => f.startsWith('stage0-wave1-receipt-') && f.endsWith('.json'));
  } catch {}

  const matchCount = DISPATCH_PATTERNS.filter(r => r.test(text)).length;
  const hasAnyEvidence = matchCount > 0 || hasWave1Receipt;

  if (!hasAnyEvidence) {
    blocks.push([
      'STAGE0 AGENT DISPATCH AUDIT — BLOCKED',
      'Verdict detected but NO evidence of agent dispatch (Wave 1/2).',
      '/stage0 v25 requires 14 agents (8 Wave 1 + 6 Wave 2).',
      '0 agents spawned = single-perspective analysis. Regenerate with full pipeline.',
    ].join('\n'));
    return;
  }

  // Count individual agent name mentions from REQUIRED_AGENTS as proxy for depth
  const agentMentions = REQUIRED_AGENTS.filter(n => hayLow.includes(n)).length;
  if (agentMentions < 8) {
    warnings.push(`⚠ STAGE0 AGENT DISPATCH: Only ${agentMentions} agent mentions detected (expected ≥14). Output may be shallow.`);
  }
}

